<script>
import BaseComponent from '@primevue/core/basecomponent';
import ScrollAreaStyle from 'primevue/scrollarea/style';

export default {
    name: 'BaseScrollArea',
    extends: BaseComponent,
    props: {
        variant: {
            type: String,
            default: 'auto'
        },
        mask: {
            type: Boolean,
            default: false
        },
        as: {
            type: [String, Object],
            default: 'DIV'
        },
        asChild: {
            type: Boolean,
            default: false
        },
        tabIndex: {
            type: Number,
            default: 0
        }
    },
    style: ScrollAreaStyle,
    provide() {
        return {
            $pcScrollArea: this,
            $parentInstance: this
        };
    }
};
</script>
